    intro: '心脏每分钟泵出约 5 升血液，靠的不是蛮力而是"单向阀系统"：房室瓣（二尖瓣、三尖瓣）守在心房与心室之间，动脉瓣（半月瓣）守在心室出口——血液向前流时门打开，想倒流时门立刻关上。听诊器里的"咚—哒"两声，正是两组瓣膜关闭的"关门声"。瓣膜一旦损坏，血液来回"倒车"，就会出现心脏杂音、心脏扩大。',
