    name: '端粒与细胞衰老',
    kicker: '细胞生物学 · 衰老的分子时钟（课外拓展）',
    intro: '端粒是染色体末端由重复 DNA 序列组成的"保护帽"，像鞋带头的塑料套防止遗传物质磨损。问题是：每次细胞分裂，端粒都会缩短一小截——短到临界值，细胞就停止分裂进入衰老（Hayflick 极限约 50 次）。生殖细胞和癌细胞靠端粒酶修复端粒而"近乎不死"，正常体细胞则几乎没有——端粒就是细胞寿命的分子时钟。',
